async (page) => {
  const tf = page.locator('vaadin-text-field input').first();
  await tf.fill('');
  await page.waitForTimeout(1500);
  const seen = new Map();
  for (let i=0;i<80;i++){
    const rows = await page.evaluate(() => {
      const g=document.querySelector('vaadin-grid');
      const out=[];
      g.querySelectorAll('vaadin-grid-cell-content').forEach(c=>out.push(c.innerText));
      g.scrollTop += 300;
      return out;
    });
    for (let j=0;j+4<rows.length;j++){ if(rows[j+2].includes('@')) seen.set(rows[j+2], rows[j+3]+'|'+rows[j+4]); }
    await page.waitForTimeout(300);
  }
  const pv=[...seen.entries()].filter(([k,v])=>v.includes('Phillips'));
  return {total:seen.size, pv};
}

