  const seen = new Map();
  await page.locator('vaadin-grid').first().hover();
  await page.mouse.wheel(0,-100000);
  await page.waitForTimeout(800);
  for (let i=0;i<150;i++){
    const rows = await page.evaluate(() => [...document.querySelectorAll('vaadin-grid-cell-content')].map(c=>c.innerText));
    for (let j=0;j+4<rows.length;j++){ if(rows[j+2].includes('@')) seen.set(rows[j+2], rows[j+3]+'|'+rows[j+4]); }
    await page.mouse.wheel(0,300);
    await page.waitForTimeout(250);
  }
  const pv=[...seen.values()].filter(v=>v.includes('Phillips'));
  return {total:seen.size, pv:pv.length, lost:pv.filter(v=>v.startsWith('Closed')).length};
}

